#!/usr/bin/env node

/**
 * Manual clink projection benchmark: monolithic versus content-defined
 * shards. Synthetic record-shaped offers are generated by
 * default; `--input PATH` measures a private LiNo file locally. Only
 * aggregate counts and durations are printed, never content.
 *
 *   CLINK_COMMAND=/path/to/clink node experiments/measure-sharded-projection.mjs \
 *     --records 2000 --monolithic-limit 1024 --concurrency 4
 */

import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { performance } from 'node:perf_hooks';

import {
  LinkCliMirror,
  parseNotation,
  splitNotation,
} from '../src/link-cli-mirror.js';
import { serializeRecords } from '../src/links-store.js';

function parseOptions(argv) {
  const options = { concurrency: 4, 'monolithic-limit': 1024, records: 2000 };
  for (let index = 0; index < argv.length; index += 2) {
    const key = argv[index]?.slice(2);
    const value = argv[index + 1];
    if (
      !value ||
      !['concurrency', 'input', 'monolithic-limit', 'records'].includes(key)
    ) {
      throw new Error(
        'Usage: measure-sharded-projection.mjs [--records N | --input PATH] [--concurrency N] [--monolithic-limit LINKS]'
      );
    }
    options[key] = key === 'input' ? value : Number(value);
  }
  if (options.input && process.env.CI) {
    throw new Error('Private input profiling is manual-only.');
  }
  return options;
}

function offers(count, edited = -1) {
  return Array.from({ length: count }, (_, index) => ({
    id: `offer-${index}`,
    price: { amount: index * 10, currency: 'VND', period: 'month' },
    sourceIds: [`source-${index % 40}`],
    text: `${index === edited ? 'Edited' : 'Room'} ${index}\nnear the beach`,
    url: `https://audit.invalid/${index}`,
  }));
}

async function timed(label, operation) {
  const started = performance.now();
  const result = await operation();
  const elapsedMs = Math.round(performance.now() - started);
  console.log(JSON.stringify({ elapsedMs, label, ...result }));
  return elapsedMs;
}

const options = parseOptions(process.argv.slice(2));
const command = process.env.CLINK_COMMAND || 'clink';
const notation = options.input
  ? await readFile(options.input, 'utf8')
  : serializeRecords('offer', offers(options.records));
const links = parseNotation(notation).length;
const shards = splitNotation(notation);
console.log(
  JSON.stringify({
    bytes: Buffer.byteLength(notation),
    concurrency: options.concurrency,
    links,
    shards: shards.length,
  })
);

const directory = await mkdtemp(join(tmpdir(), 'sharded-projection-bench-'));
try {
  let completed = 0;
  const mirror = new LinkCliMirror({
    command,
    concurrency: options.concurrency,
    onProgress: (event) => {
      if (event.status === 'shards') {
        completed = event.completed;
      }
    },
  });
  await mirror.preflight();
  await timed('sharded-cold', async () => {
    const staged = await mirror.stage({ directory, kind: 'offers', notation });
    await staged.activate();
    return { completed };
  });
  await timed('sharded-unchanged', async () => {
    await mirror.ensure({ directory, kind: 'offers', notation });
    return {};
  });
  if (!options.input) {
    const edited = serializeRecords(
      'offer',
      offers(options.records, Math.floor(options.records / 2))
    );
    let reused = 0;
    const incremental = new LinkCliMirror({
      command,
      concurrency: options.concurrency,
      onProgress: (event) => {
        if (event.status === 'shards') {
          reused = event.reused;
        }
      },
    });
    await timed('sharded-one-record-edit', async () => {
      const staged = await incremental.stage({
        directory,
        kind: 'offers',
        notation: edited,
      });
      await staged.activate();
      return { reused };
    });
  }
  if (links <= options['monolithic-limit']) {
    const monolithic = new LinkCliMirror({
      command,
      maxShardLinks: Number.MAX_SAFE_INTEGER,
    });
    await timed('monolithic-cold', async () => {
      const staged = await monolithic.stage({
        directory: join(directory, 'monolithic'),
        kind: 'offers',
        notation,
      });
      await staged.activate();
      return {};
    });
  } else {
    console.log(
      JSON.stringify({
        label: 'monolithic-cold',
        skipped: `more than ${options['monolithic-limit']} links`,
      })
    );
  }
} finally {
  await rm(directory, { force: true, recursive: true });
}
